import{_ as n,C as o,o as s,c as d,j as a,a as t,G as i,a3 as u}from"./chunks/framework.exbasbhr.js";const P=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"cn/guide/getting-started.md","filePath":"cn/guide/getting-started.md"}'),p={name:"cn/guide/getting-started.md"};function h(c,e,g,b,f,m){const r=o("ArticleMetadata"),l=o("badge");return s(),d("div",null,[e[6]||(e[6]=a("h1",{id:"快速开始",tabindex:"-1"},[t("快速开始 "),a("a",{class:"header-anchor",href:"#快速开始","aria-label":'Permalink to "快速开始"'},"​")],-1)),i(r),e[7]||(e[7]=a("h2",{id:"系统要求",tabindex:"-1"},[t("系统要求 "),a("a",{class:"header-anchor",href:"#系统要求","aria-label":'Permalink to "系统要求"'},"​")],-1)),a("ul",null,[a("li",null,[i(l,{type:"tip",text:"操作系统"}),e[0]||(e[0]=t(" Windows 10 1809（build 17763）及以上 / Windows 11"))]),a("li",null,[i(l,{type:"warning",text:"运行时"}),e[1]||(e[1]=t()),e[2]||(e[2]=a("strong",null,".NET 6 桌面运行时",-1)),e[3]||(e[3]=t("（不是 .NET Framework 4.x）"))]),a("li",null,[i(l,{type:"tip",text:"内存"}),e[4]||(e[4]=t(" 建议 4GB 以上"))]),a("li",null,[i(l,{type:"info",text:"硬件"}),e[5]||(e[5]=t(" 支持触控输入的设备（推荐，但非必需）"))])]),e[8]||(e[8]=u('<p>完整的要求与通道说明见<a href="/website/cn/guide/installation">安装与更新通道</a>。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>在<a href="/website/cn/download">下载页</a>选择更新通道后，有两种形态可选：</p><ul><li><strong>安装版（<code>.exe</code>）</strong>：运行安装向导，自动创建快捷方式，适合长期使用的设备</li><li><strong>绿色版（<code>.zip</code>）</strong>：解压到任意目录后运行 <code>InkCanvasForClass.exe</code>，不写入系统，适合便携与批量部署</li></ul><p>首次运行时，软件会引导你完成初始设置。</p><div class="warning custom-block"><p class="custom-block-title">启动失败</p><p>双击没反应或一闪而过，通常是缺少 .NET 6 桌面运行时。到微软官网下载 “.NET Desktop Runtime 6.x” 对应位数的版本安装即可。</p></div><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><h3 id="浮动工具栏" tabindex="-1">浮动工具栏 <a class="header-anchor" href="#浮动工具栏" aria-label="Permalink to &quot;浮动工具栏&quot;">​</a></h3><p>启动后会看到一个浮动工具栏，用于切换绘图工具与打开设置。</p><p><img src="https://github.com/user-attachments/assets/f47e80a8-05b8-44ab-8c70-6771e97375ea" alt="浮动工具栏" loading="lazy"></p><p>工具栏提供以下核心功能：</p><ul><li>笔工具：自由绘制，支持压感</li><li>荧光笔：半透明标记</li><li>橡皮擦：按笔画擦除或圈选擦除</li><li>颜色选择：更改笔和荧光笔颜色</li><li>撤销 / 重做</li><li>设置：访问应用程序设置</li><li>收起 / 展开：最小化工具栏</li></ul><h3 id="两种绘图模式" tabindex="-1">两种绘图模式 <a class="header-anchor" href="#两种绘图模式" aria-label="Permalink to &quot;两种绘图模式&quot;">​</a></h3><ol><li><strong>透明模式</strong>：在任何应用程序或桌面上直接标注，适合屏幕批注</li><li><strong>白板模式</strong>：提供专用绘图空间，适合板书与数学演算</li></ol><p>点击工具栏上的模式按钮即可切换。</p><h3 id="手势操作" tabindex="-1">手势操作 <a class="header-anchor" href="#手势操作" aria-label="Permalink to &quot;手势操作&quot;">​</a></h3><p>触控设备支持双指缩放、双指平移、双指点击撤销等手势。 完整列表与防误触设置见<a href="/website/cn/guide/gestures-shortcuts">手势与快捷操作</a>。</p><h3 id="保存" tabindex="-1">保存 <a class="header-anchor" href="#保存" aria-label="Permalink to &quot;保存&quot;">​</a></h3><ul><li>截屏：把当前视图连同墨迹保存为图像</li><li>自动保存：按设置周期性保存墨迹，位置见<a href="/website/cn/guide/files-and-data">配置文件与数据目录</a></li></ul><h2 id="与-powerpoint-集成" tabindex="-1">与 PowerPoint 集成 <a class="header-anchor" href="#与-powerpoint-集成" aria-label="Permalink to &quot;与 PowerPoint 集成&quot;">​</a></h2><p>ICC-CE 可以在放映幻灯片时随讲随写，并按页记住墨迹：</p><ol><li>启动 PowerPoint 并打开演示文稿</li><li>进入幻灯片放映模式</li><li>ICC-CE 自动检测到放映状态，工具栏出现翻页等专属按钮</li><li>书写的墨迹按页保存，翻页时自动切换</li></ol><p>联动原理、加载项安装与常见问题见<a href="/website/cn/guide/ppt-guide">PPT 联动指南</a>。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="/website/cn/guide/settings">设置指南</a> —— 常用配置项</li><li><a href="/website/cn/guide/advanced-tips">高级技巧</a> —— 提升效率的用法</li><li><a href="/website/cn/guide/faq">常见问题</a> —— 遇到问题先看这里</li></ul>',25))])}const w=n(p,[["render",h]]);export{P as __pageData,w as default};
